pages[10]=('Menú sugerido, no rígido',[P('Intercambia días, repite recetas y ajusta porciones. Las opciones son orientativas para adultos y pueden necesitar cambios según salud, tratamientos, alergias y preferencias.'),table,Spacer(1,16),F('Incluye fruta entera, líquidos y otros alimentos según tus necesidades. Puedes usar las 21 recetas de las páginas siguientes como inspiración, con las sustituciones de la página 7. El menú no prescribe calorías ni una restricción de carbohidratos.')])
for number,(title,content) in pages.items():
 out=io.BytesIO();c=canvas.Canvas(out,pagesize=(W,H));c.setFillColor(colors.HexColor('#f8f7f1'));c.rect(0,0,W,H,fill=1,stroke=0)
 c.setFillColor(colors.HexColor('#095b60'));c.rect(0,H-18,W,18,fill=1,stroke=0)
 c.setFont('Bold',9);c.drawString(42,H-46,'REINICIO METABÓLICO / GUÍA DE 7 DÍAS')
 flow=[Paragraph(title,styles['RMHead'])]+content
 frame=Frame(42,55,W-84,H-125,leftPadding=0,bottomPadding=0,rightPadding=0,topPadding=0)
 frame.addFromList(flow,c)
 if flow:raise RuntimeError(f'Content overflow on page {number}: {len(flow)} blocks')
 c.setFont('Body',8);c.setFillColor(colors.HexColor('#5b7474'));c.drawString(42,30,'Edición revisada - octubre 2026 / Material educativo');c.drawRightString(W-42,30,str(number));c.showPage();c.save()
 replacement=fitz.open(stream=out.getvalue(),filetype='pdf');source.delete_page(number-1)
 source.insert_pdf(replacement,from_page=0,to_page=0,start_at=number-1)
